--
-- Table structure for table `assets`
--

DROP TABLE IF EXISTS `assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assets` (
  `id` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `route_name` varchar(255) DEFAULT NULL,
  `major_category` enum('Fixed Asset','Non Fixed Asset') NOT NULL,
  `asset_type` enum('Moveable','Non Moveable','Other') DEFAULT 'Other',
  `category` varchar(255) NOT NULL,
  `brand_name` varchar(100) DEFAULT NULL,
  `model` varchar(100) DEFAULT NULL,
  `sub_type` varchar(255) DEFAULT NULL,
  `type` varchar(100) DEFAULT NULL,
  `sizes` varchar(100) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `memory_size` varchar(50) DEFAULT NULL,
  `processor` varchar(100) DEFAULT NULL,
  `generation` varchar(50) DEFAULT NULL,
  `storage_size` varchar(50) DEFAULT NULL,
  `status` varchar(100) DEFAULT 'Active',
  `division` varchar(100) DEFAULT NULL,
  `owner_division` varchar(100) DEFAULT NULL,
  `custodian_name` varchar(255) DEFAULT NULL,
  `custodian_id` varchar(50) DEFAULT NULL,
  `custodian_address` text DEFAULT NULL,
  `custodian_mobile` varchar(20) DEFAULT NULL,
  `staff_assigned_to` varchar(255) DEFAULT NULL,
  `staff_id` varchar(50) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `room_number` varchar(50) DEFAULT NULL,
  `room_name` varchar(150) DEFAULT NULL,
  `desk_number` varchar(50) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `purchase_cost` decimal(12,2) DEFAULT NULL,
  `useful_life` int(11) DEFAULT 5,
  `residual_value` decimal(12,2) DEFAULT 0.00,
  `last_service_date` date DEFAULT NULL,
  `last_inspection_date` date DEFAULT NULL,
  `approval_status` enum('Pending','Approved','Rejected') DEFAULT 'Pending',
  `notes` text DEFAULT NULL,
  `image` text DEFAULT NULL,
  `serial_number` varchar(100) DEFAULT NULL,
  `asset_tag` varchar(100) DEFAULT NULL,
  `plate_number` varchar(50) DEFAULT NULL,
  `chassis_number` varchar(100) DEFAULT NULL,
  `engine_number` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` varchar(50) DEFAULT NULL,
  `quantity` int(11) DEFAULT 1,
  `capacity` varchar(150) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `warranty_expiry` date DEFAULT NULL,
  `bank_name` varchar(150) DEFAULT NULL,
  `account_number` varchar(100) DEFAULT NULL,
  `account_type` varchar(100) DEFAULT NULL,
  `branch` varchar(150) DEFAULT NULL,
  `currency` varchar(20) DEFAULT 'GHS',
  `balance_amount` decimal(15,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_major` (`major_category`),
  KEY `idx_type` (`asset_type`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`),
  KEY `idx_division` (`division`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
